"""Algorithm 3 — Aperiodicity screen for candidate positional carriers.

Given a measured relative excess rho - 1 that a candidate classifier f is
supposed to explain, the drift budget theorem says absorption requires

    delta >= delta_star := (rho - 1) / (rho + 1),

where delta is the relative drift of f's window composition.  For an m-periodic
classifier the drift over a window of length L is bounded by m / L, so the
candidate can be rejected with no data pass at all whenever m / L < delta_star.
"""

from __future__ import annotations

from typing import Callable, Hashable, Optional, Sequence, Tuple

Class = Hashable


def required_drift(rho: float) -> float:
    """The scale-free drift budget (rho - 1) / (rho + 1)."""
    return (rho - 1.0) / (rho + 1.0)


def surviving_excess_bound(rho: float, delta: float) -> float:
    """Guaranteed lower bound rho (1-delta)/(1+delta) - 1 on the residual excess."""
    return rho * (1.0 - delta) / (1.0 + delta) - 1.0


def screen_periodic_carrier(rho: float, period: int, window_length: int) -> Tuple[bool, str]:
    """O(1) rejection test for a classifier known to be `period`-periodic.

    Returns (rejected, explanation).
    """
    d_star = required_drift(rho)
    bound = period / window_length
    if bound < d_star:
        return True, (
            f"period {period} over window {window_length} permits drift at most "
            f"{bound:.6f} < required {d_star:.6f}: cannot absorb an excess of "
            f"{rho - 1:.4f}; guaranteed surviving excess "
            f">= {surviving_excess_bound(rho, bound):.4f}"
        )
    return False, (
        f"period {period} is {100 * bound:.2f}% of the window, at or above the "
        f"required {100 * d_star:.2f}%: not excluded by the budget alone"
    )


def screen_measured_carrier(
    rho: float,
    f: Callable[[int], Class],
    starts: Sequence[int],
    window_length: int,
) -> Tuple[bool, float, str]:
    """Rejection test using a measured composition census.

    Returns (rejected, delta_max, explanation).  Cost O(|starts| * window_length).
    """
    tables = []
    for a in starts:
        counts: dict = {}
        for i in range(window_length):
            c = f(a + i)
            counts[c] = counts.get(c, 0) + 1
        tables.append(counts)
    classes: set = set()
    for t in tables:
        classes |= set(t)
    delta_max = 0.0
    for c in classes:
        vals = [t.get(c, 0) for t in tables]
        lo, hi = min(vals), max(vals)
        delta_max = max(delta_max, (hi - lo) / max(1, lo))
    d_star = required_drift(rho)
    if delta_max < d_star:
        return True, delta_max, (
            f"measured drift {delta_max:.6f} < required {d_star:.6f}: rejected; "
            f"guaranteed surviving excess "
            f">= {surviving_excess_bound(rho, delta_max):.4f}"
        )
    return False, delta_max, (
        f"measured drift {delta_max:.6f} >= required {d_star:.6f}: survives the "
        "screen and deserves a full mixture fit"
    )


def detect_period(f: Callable[[int], Class], max_period: int = 5000,
                  probes: int = 400) -> Optional[int]:
    """Smallest m <= max_period with f(j + m) == f(j) on a probe set, else None."""
    for m in range(1, max_period + 1):
        if all(f(j) == f(j + m) for j in range(-probes // 2, probes // 2)):
            return m
    return None


if __name__ == "__main__":
    rho = 1.1774
    print("drift budget:", required_drift(rho))
    for p in (7, 210, 1009, 10007):
        rejected, why = screen_periodic_carrier(rho, p, 100_000)
        print(f"period {p:>6}: rejected={rejected}  {why}")
